#!/usr/bin/env python3
"""
================================================================================
XAUUSD LOCKED METHOD  -  FROZEN BUNDLE  (self-restoring)
================================================================================

WHAT THIS IS
------------
The single authoritative copy of everything that makes the XAUUSD H4 Telegram
signal robot work. If Hermes is reinstalled, the profile is reset, or the
trading/ folder is lost, this bundle rebuilds the entire system byte-for-byte.

Files are stored base64-encoded INSIDE this script, so there are no loose
side-car files to lose. Run it from anywhere.

USAGE
-----
  python xauusd_bundle.py --verify     check the files on disk against the bundle
  python xauusd_bundle.py --restore    write missing/drifted files back
  python xauusd_bundle.py --list       show what is inside and each hash
  python xauusd_bundle.py --diff       show which files currently differ

EXIT CODES
----------
  0  everything matches (verify) or restore succeeded
  2  DRIFT - at least one file on disk differs from the bundle
  3  MISSING - at least one file is absent
  4  the bundle itself failed its own internal check

DESIGN RULE
-----------
This bundle is the BACKUP, never the source of truth during normal operation.
The locked method files in trading/ are what the robot imports. If someone
edits them, --verify says DRIFT and you must decide: was the edit intended?
If not, --restore puts the frozen bytes back.

The bundle does not carry Telegram credentials. Those are read from
tg.json at run time and are deliberately NOT baked in here.
================================================================================
"""

